using System.Numerics;
using System.Text.Json;
using ByteEngine.Core.Assets;
using ByteEngine.Core.Runtime;
internal static class PackAudit {
 internal const string Root="Assets/AnimationPacks/HumanMelee/";
 internal static void Run(GameProjectRuntime runtime){var info=new List<object>();foreach(var path in Directory.GetFiles(Program.Root+"/"+Root,"*.fbx",SearchOption.AllDirectories)){if(path.Contains("HumanF")||path.Contains("Polearm")||path.Contains("Strafe")||path.Contains("Backward")||path.Contains("Left.fbx")||path.Contains("Right.fbx")||path.Contains("ForwardLeft")||path.Contains("ForwardRight")||path.Contains("Shield"))continue;var reference=runtime.Database.ResolveReference(Path.GetRelativePath(Program.Root,path).Replace('\\','/'));var model=runtime.Assets.LoadModel(reference);Vector3 min=new(float.MaxValue),max=new(float.MinValue);foreach(var mesh in model.Meshes)for(int i=0;i<mesh.Vertices.Length;i+=8){var v=new Vector3(mesh.Vertices[i],mesh.Vertices[i+1],mesh.Vertices[i+2]);min=Vector3.Min(min,v);max=Vector3.Max(max,v);}info.Add(new{path,model.Name,meshes=model.Meshes.Count,vertices=model.Meshes.Sum(m=>m.Vertices.Length/8),bounds=new{min=min.ToString(),max=max.ToString()},bones=model.Skeleton?.Bones.Select(b=>b.Name).ToArray(),nodes=model.Nodes.Select(n=>new{n.Name,parent=n.ParentKey,position=n.LocalTransform.Translation.ToString()}).ToArray(),animations=model.Animations.Select(a=>new{a.Name,a.Duration,channels=a.Channels.Count,tracks=a.Channels.Take(5).Select(c=>new{c.NodeName,first=c.Translation?.Keys.FirstOrDefault(),last=c.Translation?.Keys.LastOrDefault()})})});Console.WriteLine($"PACK {model.Name}: meshes {model.Meshes.Count}, clips {string.Join(",",model.Animations.Select(a=>$"{a.Name} {a.Duration:0.000}s"))}");}File.WriteAllText(Program.Root+"/Preview/Melee pack audit.json",JsonSerializer.Serialize(info,new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));}
}
